VALUES ('lu-r2', '熙', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '考公弟熙弑兄自立，谥炀公，在位六年，为鲁国早期因篡弑更迭之例，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁炀公"}]'::jsonb, '炀公', NULL, '鲁炀公')
