VALUES ('lu-r3', '宰', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '炀公之子宰，谥幽公，在位十四年，承续鲁国嫡系，西周时期事迹记载疏略，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁幽公"}]'::jsonb, '幽公', NULL, '鲁幽公')
