VALUES ('lu-r4', '晞', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '幽公之子晞，谥魏公，在位近五十年，为鲁国西周时期在位时间较长之君，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁魏公"}]'::jsonb, '魏公', NULL, '鲁魏公')
