VALUES ('lu-r5', '擢', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '魏公之子擢，谥厉公，在位三十七年，属西周晚期鲁国君主，除世次外史料有限，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁厉公"}]'::jsonb, '厉公', NULL, '鲁厉公')
