VALUES ('lu-r6', '具', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '厉公之子具，谥献公，在位约三十二年，承续鲁国世系，事迹记载甚少，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁献公"}]'::jsonb, '献公', NULL, '鲁献公')
