VALUES ('lu-r7', '濞', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '献公之子濞，谥真公，在位约三十年，为春秋以前鲁国世君之一，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁真公"}]'::jsonb, '真公', NULL, '鲁真公')
