VALUES ('lu-r8', '敖', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '真公之子敖，谥武公，在位九年，承续鲁国嫡系，事迹除世次外记载有限，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁武公"}]'::jsonb, '武公', NULL, '鲁武公')
