VALUES ('lu-r9', '戏', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '武公之子戏，谥懿公，在位九年，后被侄伯御所弑，鲁国再度陷入内争，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁懿公"}]'::jsonb, '懿公', NULL, '鲁懿公')
