VALUES ('lu-r10', '伯御', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '懿公侄伯御弑君自立，在位十一年，前796年周宣王命鲁人杀伯御，立孝公称复位，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伯御"}]'::jsonb, NULL, NULL, '伯御')
