VALUES ('lu-r11', '称', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '武公之子称，谥孝公，周宣王命杀伯御后立之，在位近三十年，鲁国政局复归嫡系，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁孝公"}]'::jsonb, '孝公', NULL, '鲁孝公')
