VALUES ('lu-r12', '弗涅', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '孝公之子弗涅，谥惠公，在位四十六年，娶孟子无子，继室声子生隐公，仲子生桓公，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁惠公"}]'::jsonb, '惠公', NULL, '鲁惠公')
