VALUES ('lu-r13', '息姑', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '惠公庶长子息姑，谥隐公，因弟允年幼而摄政，《春秋》纪年起于此，前712年为羽父所弑。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁隐公"}]'::jsonb, '隐公', NULL, '鲁隐公')
