VALUES ('lu-r17', '申', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '庄公嫡子申，谥釐公，季友立之复位，先后败齐、败宋，在位三十二年，奠定鲁中期局势。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁釐公"}]'::jsonb, '釐公', NULL, '鲁釐公')
