VALUES ('lu-r18', '兴', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '釐公之子兴，谥文公，在位十八年，任用季孙、孟孙、叔孙，三桓势力渐盛，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁文公"}]'::jsonb, '文公', NULL, '鲁文公')
