VALUES ('lu-r19', '馁', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '文公之子馁，谥宣公，襄仲弑文公而立之，逆天乱常，三桓专权之势由此加剧，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁宣公"}]'::jsonb, '宣公', NULL, '鲁宣公')
