VALUES ('lu-r20', '黑肱', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '宣公之子黑肱，谥成公，在位十八年，与晋、齐会盟，鲁国已渐为大国附庸，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁成公"}]'::jsonb, '成公', NULL, '鲁成公')
