VALUES ('lu-r21', '午', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '成公之子午，谥襄公，在位三十年，三桓专国，鲁政日衰，《春秋》后期多载其会盟，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁襄公"}]'::jsonb, '襄公', NULL, '鲁襄公')
