VALUES ('lu-r22', '野', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '襄公之子野，未得谥号，即位同年赴田而死，为鲁国罕见的即位即卒之君，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/君野"}]'::jsonb, NULL, NULL, '君野')
