VALUES ('lu-r23', '稠', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '襄公之子稠，谥昭公，在位三十一年，遭三桓逼迫出奔，先后流亡齐、晋，终死于国外，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁昭公"}]'::jsonb, '昭公', NULL, '鲁昭公')
