VALUES ('lu-r24', '宋', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '昭公之弟宋，谥定公，在位十四年，孔子自卫返鲁在其任内，鲁国礼乐稍得修明，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁定公"}]'::jsonb, '定公', NULL, '鲁定公')
