VALUES ('lu-r25', '将', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '定公之子将，谥哀公，在位二十七年，孔子卒于其治世，鲁国已完全为三桓所挟持，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁哀公"}]'::jsonb, '哀公', NULL, '鲁哀公')
