VALUES ('lu-r27', '嘉', ARRAY[]::text[], '姬', '鲁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '悼公之子嘉，谥元公，在位二十年，属战国早期鲁国世君，除世次外史料疏略，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲁元公"}]'::jsonb, '元公', NULL, '鲁元公')
